pub fn dump_Stat(out: &mut impl Write, path: &str, value: &Stat<'_>) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::visit(out, path, 2121924237, value.offset_data().len(), dump_args)? {
        return Ok(());
    }
    let base = value.offset_data();
    {
        let path = &format!("{path}.version");
        let fieldValue = value.version();
        writeln!(out, "{path}.major={}", fieldValue.major)?;
        writeln!(out, "{path}.minor={}", fieldValue.minor)?;
    }
    {
        let path = &format!("{path}.designAxisSize");
        let fieldValue = value.design_axis_size();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.designAxisCount");
        let fieldValue = value.design_axis_count();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.designAxesOffset");
        let fieldValue = value.design_axes_offset();
        writeln!(out, "{path}={}", fieldValue.to_u32())?;
    }
    {
        let path = &format!("{path}.designAxes");
        let resolved = value.design_axes();
        match resolved {
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            Ok(fieldValue) => {
                writeln!(out, "{path}.length={}", fieldValue.len())?;
                for (index, item) in fieldValue.iter().enumerate() {
                    let path = &format!("{path}[{index}]");
                    crate::dump_support::set_arguments([0; 3]);
                    dump_AxisRecord(out, path, item, base)?;
                }
            }
        }
    }
    {
        let path = &format!("{path}.axisValueCount");
        let fieldValue = value.axis_value_count();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.offsetToAxisValueOffsets");
        let fieldValue = value.offset_to_axis_value_offsets();
        let rawOffset = fieldValue.offset();
        writeln!(out, "{path}={}", rawOffset.to_u32())?;
    }
    {
        let path = &format!("{path}.offsetToAxisValues");
        let target_args: [u64; 3] = [u64::from(value.axis_value_count()), 0, 0];
        crate::dump_support::set_arguments(target_args);
        match value.offset_to_axis_values() {
            None => writeln!(out, "{path}=none")?,
            Some(resolved) => match resolved {
                Ok(table) => table.dump(out, path)?,
                Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            },
        }
    }
    {
        let path = &format!("{path}.elidedFallbackNameId");
        match value.elided_fallback_name_id() {
            Some(fieldValue) => {
                writeln!(out, "{path}={}", fieldValue.to_u16())?;
            }
            None => writeln!(out, "{path}=none")?,
        }
    }
    Ok(())
}

